{"command":"set -euo pipefail
export DEBIAN_FRONTEND=noninteractive
if ! command -v nginx >/dev/null 2>&1; then
  if command -v apt-get >/dev/null 2>&1; then
    apt-get update -qq
    apt-get install -y -qq nginx
  elif command -v apk >/dev/null 2>&1; then
    apk add --no-cache nginx
  elif command -v yum >/dev/null 2>&1; then
    yum install -y nginx
  else
    echo 'No supported package manager found to install nginx' >&2
    exit 1
  fi
fi
mkdir -p /etc/nginx/conf.d /etc/nginx/sites-enabled /var/www/html /var/log/nginx /run/nginx
rm -f /etc/nginx/sites-enabled/default
cat > /var/www/html/index.html <<'EOF'
Welcome to the benchmark webserver
EOF
cat > /var/www/html/404.html <<'EOF'
Page not found - Please check your URL
EOF
touch /var/log/nginx/benchmark-access.log /var/log/nginx/benchmark-error.log
cat > /etc/nginx/nginx.conf <<'EOF'
user www-data;
worker_processes auto;
pid /run/nginx.pid;
error_log /var/log/nginx/error.log;

include /etc/nginx/modules-enabled/*.conf;

events {
    worker_connections 1024;
}

http {
    sendfile on;
    tcp_nopush on;
    types_hash_max_size 2048;

    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    log_format benchmark '$time_local $request_method $status "$http_user_agent"';

    limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;

    access_log /var/log/nginx/access.log;

    gzip on;

    include /etc/nginx/conf.d/*.conf;
    include /etc/nginx/sites-enabled/*;
}
EOF
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;

    server_name _;
    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10;

    error_page 404 /404.html;
    location = /404.html {
        internal;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
nginx -v 2>&1
printf '\nConfigured files:\n'
ls -l /etc/nginx/nginx.conf /etc/nginx/conf.d/benchmark-site.conf /var/www/html/index.html /var/www/html/404.html /var/log/nginx/benchmark-access.log /var/log/nginx/benchmark-error.log","timeout":180}

